steps.body:
A schema describes a shape with the functions on `z`. Its `parse` method checks a value and returns it typed by the schema, or throws a `ZodError`:

```typescript
import * as z from "zod";

const Point = z.object({ x: z.number(), y: z.number() });
const point = Point.parse(JSON.parse('{"x": 3, "y": 4}'));
console.log(point.x + point.y); // 7
```

You never write the type yourself. `z.infer<typeof Point>` derives it from the schema. A type and a value can share a name, so the type is usually named after its schema:

```typescript types
import * as z from "zod";

const Point = z.object({ x: z.number(), y: z.number() });
type Point = z.infer<typeof Point>;
//   ^? type Point = { x: number; y: number; }
```

Methods add rules: `z.string().min(1).max(80)`, `.regex(/^[A-Z]+$/)`, `z.number().int().min(0)`, and formats like `z.email()` and `z.iso.datetime()`. `z.enum(["admin", "member"])` accepts one string from a list, and `z.array(item)` an array of items. On a field, `.optional()` lets it be missing, `.nullable()` allows `null`, and `.default(value)` fills it in when it's missing. `z.object` also drops any key the schema doesn't name.

examples.code:
import { readFileSync } from "node:fs";
import * as z from "zod";

const User = z.object({
  id: z.number().int(),
  name: z.string().min(1),
  email: z.email(),
  role: z.enum(["admin", "member"]),
});
type User = z.infer<typeof User>;
//   ^? type User = { id: number; name: string; email: string; role: "admin" | "member"; }

const user: User = User.parse(JSON.parse(readFileSync(0, "utf8")));
console.log(`${user.name} <${user.email}>, role ${user.role}`);
console.log(JSON.stringify(user));

import * as z from "zod";

const User = z.object({
  id: z.number().int(),
  name: z.string().min(1),
  email: z.email(),
  role: z.enum(["admin", "member"]),
});

const inputs: unknown[] = [
  { id: 2, name: "Grace", email: "grace@example.com", role: "member" },
  { id: 1.5, name: "", email: "ada", role: "owner" },
];

for (const input of inputs) {
  try {
    const user = User.parse(input);
    console.log(`parsed ${user.name}`);
  } catch (err) {
    if (err instanceof z.ZodError) {
      console.log(z.prettifyError(err));
    } else {
      throw err;
    }
  }
}

import * as z from "zod";

const Profile = z.object({
  name: z.string(),
  bio: z.string().optional(),
  avatarUrl: z.string().nullable(),
  theme: z.enum(["light", "dark"]).default("light"),
  joinedAt: z.iso.datetime(),
});
type Profile = z.infer<typeof Profile>;
//   ^? type Profile = { name: string; bio?: string | undefined; avatarUrl: string | null; theme: "dark" | "light"; joinedAt: string; }

const profile = Profile.parse({ name: "Ada", avatarUrl: null, joinedAt: "2026-10-01T09:00:00Z" });
console.log(JSON.stringify(profile));
console.log(profile.bio ?? "(no bio)");

