import { readFileSync } from "node:fs";
import * as z from "zod";

export const Signup = z.object({
  email: z.email(),
  password: z.string().min(8, "Password must be at least 8 characters"),
  age: z.number().int("Age must be a whole number").min(13, "You must be at least 13"),
});

const data: unknown = JSON.parse(readFileSync(0, "utf8"));
const result = Signup.safeParse(data);
if (result.success) {
  console.log("ok");
} else {
  const lines: string[] = [];
  const { fieldErrors } = z.flattenError(result.error);
  for (const [field, messages] of Object.entries(fieldErrors)) {
    for (const message of messages) {
      lines.push(`${field}: ${message}`);
    }
  }
  console.log(lines.toSorted().join("\n"));
}

steps.body:
`z.discriminatedUnion(key, options)` builds a tagged union from object schemas that share a tag field, written with `z.literal`. Its inferred type is the discriminated union you'd write by hand, so checking the tag narrows it:

```typescript
import * as z from "zod";

const Shape = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("circle"), radius: z.number() }),
  z.object({ kind: z.literal("square"), side: z.number() }),
]);
const shape = Shape.parse({ kind: "square", side: 3 });
console.log(shape.kind === "square" ? shape.side ** 2 : 0); // 9
```

`.refine(check, { error, path })` adds a rule that types can't express, like one field that depends on another. `path` names the field the issue belongs to, so the message lands on that field instead of on the whole object.

Object schemas also mirror the utility types. `.pick({ id: true })` is `Pick`, `.omit` is `Omit`, `.partial()` is `Partial`, and `.extend({ ... })` adds fields. Each returns a new schema, so one base schema can serve a summary, a create form, and a patch.

examples.code:
import { readFileSync } from "node:fs";
import * as z from "zod";

const Payment = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("card"), last4: z.string().length(4) }),
  z.object({ kind: z.literal("paypal"), email: z.email() }),
  z.object({ kind: z.literal("bank"), iban: z.string() }),
]);
type Payment = z.infer<typeof Payment>;
//   ^? type Payment = { kind: "card"; last4: string; } | { kind: "paypal"; email: string; } | { kind: "bank"; iban: string; }

function receiptLine(payment: Payment): string {
  switch (payment.kind) {
    case "card":
      return `Paid by card ending ${payment.last4}`;
    case "paypal":
      return `Paid with PayPal (${payment.email})`;
    case "bank":
      return `Paid by bank transfer from ${payment.iban.slice(0, 4)}...${payment.iban.slice(-4)}`;
  }
}

const result = z.array(Payment).safeParse(JSON.parse(readFileSync(0, "utf8")));
if (result.success) {
  for (const payment of result.data) {
    console.log(receiptLine(payment));
  }
} else {
  console.log(z.prettifyError(result.error));
}

const cash = Payment.safeParse({ kind: "cash" });
if (!cash.success) {
  console.log(z.prettifyError(cash.error));
}

import * as z from "zod";

const Booking = z
  .object({
    room: z.string(),
    start: z.iso.datetime(),
    end: z.iso.datetime(),
  })
  .refine((b) => Date.parse(b.end) > Date.parse(b.start), {
    error: "end must be after start",
    path: ["end"],
  });

const bookings: unknown[] = [
  { room: "Ada", start: "2026-10-01T09:00:00Z", end: "2026-10-01T10:30:00Z" },
  { room: "Babbage", start: "2026-10-01T11:00:00Z", end: "2026-10-01T10:00:00Z" },
  { room: "Curie", start: "2026-10-01T11:00:00Z", end: "noon" },
  { room: "Dijkstra", start: "2026-10-01T11:00:00Z" },
];

for (const input of bookings) {
  const result = Booking.safeParse(input);
  if (result.success) {
    console.log(`booked ${result.data.room}`);
  } else {
    console.log(JSON.stringify(z.flattenError(result.error).fieldErrors));
  }
}

