practice.solution:
import { readFileSync } from "node:fs";
import * as z from "zod";

export const WebhookEvent = z.discriminatedUnion("type", [
  z.object({
    type: z.literal("order.paid"),
    orderId: z.string(),
    amountCents: z.number().int(),
  }),
  z.object({
    type: z.literal("order.refunded"),
    orderId: z.string(),
    amountCents: z.number().int(),
    reason: z.string(),
  }),
  z.object({
    type: z.literal("customer.deleted"),
    customerId: z.string(),
  }),
]);
export type WebhookEvent = z.infer<typeof WebhookEvent>;

function dollars(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

export function summarize(event: WebhookEvent): string {
  switch (event.type) {
    case "order.paid":
      return `${event.orderId} paid ${dollars(event.amountCents)}`;
    case "order.refunded":
      return `${event.orderId} refunded ${dollars(event.amountCents)} (${event.reason})`;
    case "customer.deleted":
      return `customer ${event.customerId} deleted`;
  }
}

const data: unknown = JSON.parse(readFileSync(0, "utf8"));
const result = z.array(WebhookEvent).safeParse(data);
if (result.success) {
  for (const event of result.data) {
    console.log(summarize(event));
  }
} else {
  console.log(z.prettifyError(result.error));
}
